1007:   function _withdraw(
1008:     address _caller,
1009:     address _receiver,
1010:     address _owner,
1011:     uint256 _assets,
1012:     uint256 _shares
1013:   ) internal virtual override {
1014:     if (_caller != _owner) {
1015:       _spendAllowance(_owner, _caller, _shares);
1016:     }
1017: 
1018:     // If _asset is ERC777, `transfer` can trigger a reentrancy AFTER the transfer happens through the
1019:     // `tokensReceived` hook. On the other hand, the `tokensToSend` hook, that is triggered before the transfer,
1020:     // calls the vault, which is assumed not malicious.
1021:     //
1022:     // Conclusion: we need to do the transfer after the burn so that any reentrancy would happen after the
1023:     // shares are burned and after the assets are transferred, which is a valid state.
1024:     _burn(_owner, _shares);
1025: 
1026:     _yieldVault.withdraw(_assets, address(this), address(this));
1027:     SafeERC20.safeTransfer(IERC20(asset()), _receiver, _assets);
1028: 
1029:     emit Withdraw(_caller, _receiver, _owner, _assets, _shares);
1030:   }

230:     function _withdraw(
231:         address caller,
232:         address receiver,
233:         address owner,
234:         uint256 assets,
235:         uint256 shares
236:     ) internal virtual {
237:         if (caller != owner) {
238:             _spendAllowance(owner, caller, shares);
239:         }
240: 
241:         // If _asset is ERC777, `transfer` can trigger a reentrancy AFTER the transfer happens through the
242:         // `tokensReceived` hook. On the other hand, the `tokensToSend` hook, that is triggered before the transfer,
243:         // calls the vault, which is assumed not malicious.
244:         //
245:         // Conclusion: we need to do the transfer after the burn so that any reentrancy would happen after the
246:         // shares are burned and after the assets are transferred, which is a valid state.
247:         _burn(owner, shares);
248:         SafeERC20.safeTransfer(_asset, receiver, assets);
249: 
250:         emit Withdraw(caller, receiver, owner, assets, shares);
251:     }

509:   function withdraw(
510:     uint256 _assets,
511:     address _receiver,
512:     address _owner
513:   ) public virtual override returns (uint256) {
514:     if (_assets > maxWithdraw(_owner))
515:       revert WithdrawMoreThanMax(_owner, _assets, maxWithdraw(_owner));
516: 
517:     uint256 _shares = _convertToShares(_assets, Math.Rounding.Up);
518:     _withdraw(msg.sender, _receiver, _owner, _assets, _shares);
519: 
520:     return _shares;
521:   }

524:   function redeem(
525:     uint256 _shares,
526:     address _receiver,
527:     address _owner
528:   ) public virtual override returns (uint256) {
529:     if (_shares > maxRedeem(_owner)) revert RedeemMoreThanMax(_owner, _shares, maxRedeem(_owner));
530: 
531:     uint256 _assets = _convertToAssets(_shares, Math.Rounding.Down);
532:     _withdraw(msg.sender, _receiver, _owner, _assets, _shares);
533: 
534:     return _assets;
535:   }

177:     function withdraw(uint256 assets, address receiver, address owner) public virtual override returns (uint256) {
178:         require(assets <= maxWithdraw(owner), "ERC4626: withdraw more than max");
179: 
180:         uint256 shares = previewWithdraw(assets);
181:         _withdraw(_msgSender(), receiver, owner, assets, shares);
182: 
183:         return shares;
184:     }

187:     function redeem(uint256 shares, address receiver, address owner) public virtual override returns (uint256) {
188:         require(shares <= maxRedeem(owner), "ERC4626: redeem more than max");
189: 
190:         uint256 assets = previewRedeem(shares);
191:         _withdraw(_msgSender(), receiver, owner, assets, shares);
192: 
193:         return assets;
194:     }

864:   function _convertToShares(
865:     uint256 _assets,
866:     Math.Rounding _rounding
867:   ) internal view virtual override returns (uint256) {
868:     uint256 _exchangeRate = _currentExchangeRate();
869: 
870:     return
871:       (_assets == 0 || _exchangeRate == 0)
872:         ? _assets
873:         : _assets.mulDiv(_assetUnit, _exchangeRate, _rounding);
874:   }

882:   function _convertToAssets(
883:     uint256 _shares,
884:     Math.Rounding _rounding
885:   ) internal view virtual override returns (uint256) {
886:     return _convertToAssets(_shares, _currentExchangeRate(), _rounding);
887:   }

123:     function maxWithdraw(address owner) public view virtual override returns (uint256) {
124:         return _convertToAssets(balanceOf(owner), Math.Rounding.Down);
125:     }

128:     function maxRedeem(address owner) public view virtual override returns (uint256) {
129:         return balanceOf(owner);
130:     }

925:   function _deposit(
926:     address _caller,
927:     address _receiver,
928:     uint256 _assets,
929:     uint256 _shares
930:   ) internal virtual override {
931:     IERC20 _asset = IERC20(asset());
932:     uint256 _vaultAssets = _asset.balanceOf(address(this));
933: 
934:     // If _asset is ERC777, `transferFrom` can trigger a reentrancy BEFORE the transfer happens through the
935:     // `tokensToSend` hook. On the other hand, the `tokenReceived` hook that is triggered after the transfer
936:     // calls the vault which is assumed to not be malicious.
937:     //
938:     // Conclusion: we need to do the transfer before we mint so that any reentrancy would happen before the
939:     // assets are transferred and before the shares are minted, which is a valid state.
940: 
941:     // We only need to deposit new assets if there is not enough assets in the vault to fulfill the deposit
942:     if (_assets > _vaultAssets) {
943:       uint256 _assetsDeposit;
944: 
945:       unchecked {
946:         if (_vaultAssets != 0) {
947:           _assetsDeposit = _assets - _vaultAssets;
948:         }
949:       }
950: 
951:       SafeERC20.safeTransferFrom(
952:         _asset,
953:         _caller,
954:         address(this),
955:         _assetsDeposit != 0 ? _assetsDeposit : _assets
956:       );
957:     }
958: 
959:     _yieldVault.deposit(_assets, address(this));
960:     _mint(_receiver, _shares);
961: 
962:     emit Deposit(_caller, _receiver, _assets, _shares);
963:   }

1122:   function _mint(address _receiver, uint256 _shares) internal virtual override {
1123:     _twabController.mint(_receiver, uint96(_shares));
1124:     _updateExchangeRate();
1125: 
1126:     emit Transfer(address(0), _receiver, _shares);
1127:   }
